Formally in this paper, $x \in (\R_{\geq 0})^{\binom{[n]}{2}}$ is called a {\em metric} if for every distinct $i, j, k \in [n]$, $x(i, j) \leq x(i, k) + x(j, k)$.

\paragraph*{Metric Violation Distance.} Hence we study the following \mvd problem: Given $x \in \R_{\geq 0}^{\binom{[n]}{2}}$, find $y \in M_n$ that minimizes $\|x - y\|_0$, where $M_n \subseteq \R^{\binom{n}{2}}$ is the set of all metrics on $n$ points.   

\begin{algorithm}[t]
{\bf Input:} $n \in \N$, $x \in \R_{\gz}^{\nct}$, 
    {\bf Goal:} modify $x$ to a metric.\\
    \If{$n \leq 2$}{{\bf return}}

    Choose the pivot $i \in [n]$ uniformly at random\;
    \For{$j \neq k \in [n] \setminus \{ i \}$}{
    \If{$x(j, k) > x(i, j) + x(i, k)$}{
        $x(j, k) = x(i, j) + x(i, k)$;
    }
    \If{$x(j, k) < |x(i, j) - x(i, k)|$}{
    $x(j, k) = |x(i, j) - x(i, k)|$;
    }
    }
    \textsc{MVD-Pivot}$(n - 1, x|_{\binom{[n]\setminus i}{2}})$ \tcp*{$x|_{\binom{[n]\setminus i}{2}}$ is $x$ restricted to $\{ (j, k) \in \binom{[n] \setminus \{ i \} }{2} \}$}
    {\bf return}
 \caption{\textsc{MVD-Pivot}$(n, x)$}
 \label{algo:mvd}
\end{algorithm}

We view the input distance data $x$ as a family of weights on the edges of a complete graph. A \textit{triangle} is a triple of vertices, or equivalently of edges. Let $ij$ be an edge belonging to a triangle $t=ijk$. If $x(ij) > x(ik)+ x(jk)$, we say that the edge $ij$ is in \textit{excess}. If $x(ij) < |x(ik) -x(jk)|$, we say that it is in \textit{deficit}. In both cases we call the triangle $t$ \textit{unbalanced}. After pivoting at a vertex $i$, the weights of the edges adjacent to $i$ never change in the remaining recursive calls, thus we say that they are \textit{frozen}.

 \begin{observation}\label{O:balance}
 At the end of a recursive call of Algorithm~\ref{algo:mvd} where $i$ was chosen as a pivot, none of the triangles adjacent to $i$ are unbalanced.
 \end{observation}

 We denote by $\mathcal{T}$ the set of all triangles, and by $\mathcal{T}'$ the set of all unbalanced triangles.

A hitting set for $\mathcal{T}'$ is a set of edges $H$ so that each triangle of $\mathcal{T}'$ contains at least one edge of $H$. A fractional packing for a set of triangles $\mathcal{T}'$ is a  set of values $(p_t)_{t\in \mathcal{T}'}$ so that for each edge $e$, we have $\sum_{t \ni e}p_t\leq 1$. The value of the fractional packing is $\sum_{t\in \mathcal{T'}}p_t$.

\begin{lemma}\label{L:LP}
Any solution of \mvd is at least the value of the smallest hitting set for $\mathcal{T}'$, which is itself lower bounded by the maximal value of a fractional packing of triangles in $\mathcal{T}'$.
\end{lemma}


